NAME = 'sml_BL_2008: Kitab Awal-Jaman maka Kitab Injil'
BOOK = 'I Thessalonians'

CHAPTERS = {
    1: {
        1: "Sulat itu min aku, si Paul, maka min sehe'ku si Silas maka si Timuti, pinasampay pi'ilu ni palhimpunan Tessaloneka, ya suku' Mma'tam Tuhan maka Panghū'tam si Isa Al-Masi. Mura-murahan, bang pa'in kam pinaniya'an tatabangan maka kasannangan.",
        2: "Magsukul kami ni Tuhan ma sababbi sakahaba' waktu kapangamu'-ngamu' kami ni Tuhan.",
        3: "Nientom kam ma alopan Mma'tam Tuhan, nientom kahāpan ya hinangbi luwas min pangandolbi, nientom pagsangsā'bi ma sabab lasabi ma iya, maka kahogot imanbi isab ma sabab Panghū' Isa Al-Masi ya pangasahanbi.",
        4: "Saga dauranakan, ka'am kinalasahan e' Tuhan, kata'uwan kami in ka'am bay tapene' e'na.",
        5: "Sabab ngga'i ka pangupama manusiya' ya panganasihat kami ma ka'am, sagō' lapal abarakat bay min Rū Tuhan, angkan ahogot pagsab'nnalbi. Kata'uwanbi bay bowahan kami waktu kat'nna' kami ma ka'am bo' ahāp kahālanbi.",
        6: "Bay sunuranbi kajarihan kami maka kajarihan Panghū'tam. Minsan kalabayanbi katiksa'an abisa, tinaima' e'bi lapal itu, lāgi kinōgan kam sabab min Rū Sussi.",
        7: "Angkan buwattina'an, ka'am ya panunuran e' kamemon saga a'a magpangandol ma lahat Makidunya maka ma lahat Akaya.",
        8: "Pasaplag isāb lapal pasal Panghū' Isa sabab min ka'am, pasampay ni kaluha'an lahat Makidunya maka Akaya. Ngga'i ka hal jadjahan ina'an, pasaplag habal pasal pangandolbi ni Tuhan ni sabarang lahat. Minsan kami mbal na ah'lling,",
        9: "sabab amissala na pa'in saga a'a inān pasal kapanaima'bi ma kami. Tabissala pasal kapang'bbabi min ta'u-ta'u ya bay pagtuhananbi tagna' bo' kam papinda angisbat Tuhan b'nnal, ya kakkal salama-lama.",
        10: "Angagad kono' kam ma waktu kapi'itu min sulga' Anakna, ya bay pakallumna min kamatayna. Si Isa ko' inān, ya angalappas kitam min mulka' song pinat'kka ni saga manusiya'.",
    },
    2: {
        1: "Saga dauranakanku, kata'uwanbi aheya kapūsan l'ngngan kami pi'ilu ni ka'am.",
        2: "Kata'uwanbi asal, bay kami makalabay kabinasahan ma da'ira Pilipi maka landu' nihina', sago' magsukul ni Tuhan, bay kami makatawakkal angahaka'an ka'am lapalna ahāp minsan aheka anagga'.",
        3: "Ya pamandu' kami ma ka'am halam aniya' sā'na, halam aniya' mohotna ala'at, halam aniya' niyat kami angakkalan kami.",
        4: "Tabista kami e' Tuhan makajari pinangandolan lapal ahāp itu. Mbal kami angangut anulut manusiya' sagō' Tuhan, ya makaliling deyom pikilantam.",
        5: "Kata'uwanbi haliluwal kami, halam kami bay angalanahan a'a minsan sai bo' tabowa am'nnal, halam kami magbau'-bau' in kami asaltun bo' pa'in sinōd bahaya pilak. Tuhan ya saksi' kami.",
        6: "Halam isab kami bay amiha mahaltabat min manusiya', ai na ka min ka'am atawa min a'a saddī. Minsan kami taga-kapatut pagka kawakilan Al-Masi, halam kami bay angahagda atawa amabuhat ka'am.",
        7: "Gom pa'in ahanunut pah'lling kami ma ka'am, buwat d'nda angupiksa' saga anakna.",
        8: "Aheya lasa kami ma ka'am, ya po'on kami lilla' angahaka'an ka'am pasal lapal ahāp min Tuhan. Lāgi pamalilla' baran kami sampay ni kamatay, ma sabab kaheya lasa kami ma ka'am.",
        9: "Tantu taentombi, saga dauranakan, bay paglu'ug kami waktu kamailu kami ma ka'am. Bay kami maghulas-sangsā' llaw-sangom bo' aniya' kalluman kami, supaya halam sai-sai kabuhatan sat'ggol kami anganasihatan ka'am lapal Tuhan.",
        10: "Kasaksi'anbi, maka kasaksi'an isab e' Tuhan, bang buwattingga bay tebong kami ma deyomanbi saga a'a magpangandol. Abontol sadja kami, halam aniya' kasā'an.",
        11: "Kata'uwanbi isab bay addat kami ma ka'am pakaniya-pakaniya, sali' addat matto'a ma saga anakna lahasiya'.",
        12: "Bay pahogot kami imanbi, bay palasig kami pangatayanbi, bay kam sinō' amahāp kaul-pi'ilbi bo' tōp ma Tuhan, ya amowa ka'am palamud ma pagparintahanna maka ma kasahaya'anna.",
        13: "Magsukul na pa'in kami ni Tuhan sabab mbal takalipat kami bay kapanaima'bi lapal palman. Takalebi min kami bo' pa'in ngga'i ka lapal manusiya' ya taima'bi sagō' palman sab'nnal-b'nnal min Tuhan, palman amowa na pa'in ma deyom pangatayan sasuku magkahagad.",
        14: "Dauranakanku, panunuranbi na pakaradja'an ya kalabayan e' saga jama'a si Isa Al-Masi ya ma palhimpunan lahat Yahudiya. Sabab ya du ka'am bay nila'at e' pagkahibi dabangsa, buwat bay pangala'at sigām e' pagkahi sigām Yahudi.",
        15: "Bay pinapatay e' sigām Panghū' Isa, maka pinapatay isab kanabi-nabihan ma awal lagi'. Mbal sigām makasulut atay Tuhan maka sinagga' e' sigām saga a'a kamemon.",
        16: "Sinagga' kami e' sigām bo' mbal tapagnasihat lapal ahāp ma saga a'a bangsa liyu, ya ngga'i ka Yahudi sabab mbal bilahi bang bangsa liyu lappasan min dusa. Mbal sigām pahali angalandu'an dusa sigām, ya angkan pinataluwa'an mulka' Tuhan.",
        17: "Saga dauranakanku, pagka kami bay magokat maka ka'am minsan mbal at'ggol, landu' kami angentom ati atuyu' to'ongan kami amowa mag'nda' maka ka'am pabīng. Minsan kami alawak min ka'am buwattina'an, itiya' kam ma deyom pikilan kami.",
        18: "Bilahi kami patibaw ni ka'am, paligay aku itu, si Paul. Min pila aku bay magsakap pi'ilu, sagō' pinat'nna'an aku bimbang e' nakura' saitan, ya angkan halam makalanjal.",
        19: "Na, ka'am ya pagsababan pagkōg-koyagan kami maka kaholatan kami. Maka ka'am ya pamantugan kami ma matahan Panghū'tam si Isa bang ta'abut waktu pagbīngna pi'itu.",
        20: "Aho' b'nnal, ka'am ya pamantugan maka pagkōg-koyagan kami.",
    },
    3: {
        1: "Na, pagka mbal kasandalan pangentom kami ma ka'am, anganiyat kami amatibaw si Timuti pi'ilu, bo' kami duwangan ta'bba ma da'ira Aten itu. Si Timuti itu, danakan kami asal maka sehe' kami maghinang kahinangan Tuhan. Magbeya' kami magnasihat lapal ahāp pasal Al-Masi. Pinatibaw iya pi'ilu bo' amahogot imanbi maka amakosog pangandolbi ma Tuhan.",
        2: "Na, pagka mbal kasandalan pangentom kami ma ka'am, anganiyat kami amatibaw si Timuti pi'ilu, bo' kami duwangan ta'bba ma da'ira Aten itu. Si Timuti itu, danakan kami asal maka sehe' kami maghinang kahinangan Tuhan. Magbeya' kami magnasihat lapal ahāp pasal Al-Masi. Pinatibaw iya pi'ilu bo' amahogot imanbi maka amakosog pangandolbi ma Tuhan.",
        3: "Ya kabaya'an kami subay halam aniya' tabowa maghenggol-henggol imanna ma sabab kabinasahan ya kalabayanbi ilu. Kata'uwanbi asal, pinakadal kitam kabinasahan pagka suku' Al-Masi.",
        4: "Bay sa kam nihaka'an waktu kamailu kami, in kitam suku' Al-Masi tantu t'kkahan kabinasahan. Jari kasakupanbi na, paniya' na bay pangahaka kami.",
        5: "Angkanna, pagka mbal na kasandalanku susaku ma kahālanbi, bay soho'ku si Timuti pi'ilu angahati ka'am bang masi ahogot pagimanbi ma si Isa Al-Masi. Ya kahanggawanku, kalu kam bay tasasat e' nakura' saitan, sabab bang kam tabowa e' sasat saitan, kaliman bay hinang kami mailu.",
        6: "Daipara itiya' na si Timuti baha'u bay at'kka min ka'am, maka ahāp to'ongan habal ya tabowana pasalbi. Yukna ahogot masi pagimanbi ma Tuhan maka masi na pa'in paglasabi dangan maka dangan. Yukna isab ahāp ataybi tudju ni kami itu, maka aheya baya'bi ang'nda' kami, buwat kaheya baya' kami mag'nda' maka ka'am.",
        7: "Angkanna, saga dauranakan, minsan kami ma deyom kasigpitan maka kabinasahan, ahogot du atay kami sabab makata'u na kami in ka'am halam apinda min pangandolbi ma Tuhan.",
        8: "Ahāp na palnyawahan kami pagka kata'uwan kami in pameya'bi ma Panghū' Isa atotog du.",
        9: "Magsukul na kami ni Tuhan ma sababbi, sabab ka'am ya po'onna angkan aheya kakōgan kami ma matahanna.",
        10: "Llaw-sangom atukid kami angamu'-ngamu' ni Tuhan, bang pa'in kami mag'nda' maka ka'am, bo' kam katabangan kami bang aniya' mbal gi' jukup ma pagimanbi.",
        11: "Mura-murahan, bang pa'in kami tinabang e' Mma'tam Tuhan maka e' Panghū'tam si Isa bo' kami makatūy pi'ilu ni ka'am.",
        12: "Mura-murahan isab, bang pa'in kam tinabang e' Panghū'tam bo' lumabihan lasabi ma saga sehe'bi dambeya'an ilu sampay ma manusiya' kamemon, buwat isab lasa kami ma ka'am.",
        13: "Bang pa'in pinatotog ataybi e' Panghū' supaya kam asussi maka saltun ma matahan Mma'tam Tuhan ma waktu kabalik pi'itu Panghū' Isa, beya' maka ba'anan a'a suku'na.",
    },
    4: {
        1: "Na, saga dauranakan, buwattitu hatulanna. Bay kam pandu'an kami bang kaul-pi'il ingga ya makasulutan Tuhan. Buwattē' asal kaul-pi'ilbi, Sagō' buwattina'an, pagka aniya' kapatut kami min Panghū' Isa, amu'ta kam maka soho'ta kam amuspus to'ongan ma kaul-pi'il ahāp.",
        2: "Kata'uwanbi du, in pamandu' kami ma ka'am asal min kapatut Panghū' Isa.",
        3: "Ya kabaya'an Tuhan subay asussi deyom ataybi. Da'a kam maghinang kala'atan d'nda maka l'lla.",
        4: "Ka'am kal'llahan, subay ahantap e'bi amowa h'ndabi ma halam aniya' sabulna, maka subay ahatul addatbi ma sigām.",
        5: "Da'a parūlunbi napsu baranbi magba'is-ba'is, buwat saga a'a mbal magmatāw ma Tuhan.",
        6: "Na, bang takdil ni napsu baran itu, da'a to'ongan kam angahinang la'at ma pagkahibi bebeya'an si Isa. Da'a isab kam angulli' ai-aina sabab bininasa e' Panghū' sasuku magdusa buwattē'. Bay kam pata'u kami pasal palkala' itu ma waktu tagna' gi', bay na kam asal banda'an kami.",
        7: "Pinene' kitam e' Tuhan supaya anuyu'an palantara asaltun, da'a paghinang kala'atan d'nda maka l'lla.",
        8: "Jari sasuku anaikutan pandu' itu, Tuhan ya taikutanna, ngga'i ka manusiya'. Lāgi Tuhan ya amuwanan ka'am Rū-na Sussi.",
        9: "Na, minsan kam mbal sinulatan pasal paglasabi maka pagkahibi angandol ma Al-Masi, sabab kapandu'an kam e' Tuhan, subay maglasa-liyasahi dangan maka dangan.",
        10: "Maka alasa du kam asal ma saga danakanbi kamemon magpangandol ma si Isa, ina'an ma kaluha'an lahat Makidunya ilu. Sagō' amu'ta kam, saga dauranakan, pasōngunbi gi' lasabi ma sigām.",
        11: "Tuyu'inbi ai-ai amowa ni kasannangan. Tukirinbi hinangbi luggiya', da'a kam anasaw ma hinang pagkahibi. Magusaha'an kam di-bi bo' aniya' kallumanbi, buwat bay panoho'an kami ma ka'am dahū.",
        12: "Manjari bang beya'bi panoho'an itu, pinagaddatan kam e' saga a'a minsan sigām mbal angandol ma si Isa, ati mbal kam asukkal ma kalluman.",
        13: "Na, saga dauranakanku, bilahi kami amahati ka'am pasal saga a'a angandol ma si Isa Al-Masi bang sigām ganta' amatay na. Subay kam mbal magdukka buwat saga a'a kasehe'an, ya halam aniya' pangasa-ngasahan sigām allum pabalik.",
        14: "Am'nnal kitam in si Isa bay amatay ati allum pabīng, angkan kitam am'nnal bang amatay saga a'a ya angandol ma si Isa, pinakallum du sigām pabīng e' Tuhan ati paronganna sigām ma si Isa ma waktu pagbīngna.",
        15: "Pamandu' kami itu bay min Panghū' Isa, ya yukna in kitam masi allum ma waktu kabīngna pi'itu, mbal du parahū min saga a'a magpatayan.",
        16: "Sabab dahū aniya' lling pagtawag akosog, maka suwala nakura' mala'ikat, maka lling tiyup-tiyup min Tuhan. Magtūy saru'un-du'un ya t'kka Panghū' min sulga'. Puwas e' pinabangun dahū saga a'a bay magpatayan, a'a asal bay angandol ma Al-Masi.",
        17: "Puwas e' kitam ya masi allum ma dunya itu, binowa du magdongan maka sigām pa'angkat ni diyata' gabun bo' anampang Panghū'tam ma tonga'an ayan. Manjari parakayu' kitam ma Panghū' sampay ni kasaumulan.",
        18: "Angkan pangahaka'unbi saga bissala itu dangan ni dangan, bo' supaya ahogot pangatayanbi.",
    },
    5: {
        1: "Na, saga dauranakan, in pasal masa sinōng maka pakaradja'anna, minsan kami mbal na anulatan ka'am.",
        2: "Sabab kata'uwanbi du, ya llaw kapi'itu Panghū' magtagha' sadja sali' hantang a'a anangkaw ma sangom, mbal kinata'uwan bang sumiyan ya kat'kkana.",
        3: "Bang aniya' a'a magupama in sigām asannang na, maka halam aniya' kapiligduhan, magtūy sigām t'kkahan bala' sabu pa'in sigām ah'lling. Mbal sigām makalahi sabab tagha' sadja t'kka bala' he', sapantun d'nda song anganak bang patagha' p'ddi'na.",
        4: "Sagō' ka'am ilu, saga dauranakanku, ngga'i ka ma deyom kalendoman, angkan kam subay mbal kinobla'an bang patagha' ya t'kka llaw ina'an-i, buwat kakobla' a'a bang aniya' sugarul anōd luma'na.",
        5: "Sabab ka'am ilu sali' a'a porol ma kasawahan, ngga'i ka ma kalendoman.",
        6: "Angkanna kitam subay mbal makasali' ni saga a'a kasehe'an, ya magtulihan sadja. Subay kita pajaga, maka subay ahāp pamikiltam.",
        7: "Sarang na waktu sangom pagtuli a'a, maka sangom isab ya waktu paglalango saga a'a magi'inum.",
        8: "Sagō' kitam, pagka ma deyom kasawahan na, subay ahāp pamikiltam, ngga'i ka buwat pamikil a'a maglalango. Kitam magpangandol ma si Isa sali' dalil sundalu magtinampan. Ya panampan daggahata, ya na pangandolta ni Tuhan maka lasata. Ya panurung kōkta, ya na kaholatanta ma Tuhan in kitam kalappasan du.",
        9: "Halam kitam bay pinene' e' Tuhan supaya kitam pinananam mulka'na, sagō' supaya kitam lappasan ma sabab si Isa Al-Masi ya Panghū'tam.",
        10: "Bay iya amatay ganti'tam bo' supaya kitam pat'nna' ma iya, ai na ka amatay, ai na ka allum lagi' ma waktu kapi'ituna.",
        11: "Angkan kam subay amahogot atay sehe'bi dangan maka dangan. Subay kam magtabang-tiyabangi buwat asal kabiyaksahanbi.",
        12: "Na, saga dauranakan, aniya' gi' pangamu' kami ma ka'am. Pagaddatinbi saga a'a pagnakura'anbi ma deyoman Panghū' Isa. Atukid sigām maghinang ma deyomanbi, amandu'an ka'am pasal addat-tabi'at maka hinang ya makasulut iya.",
        13: "Pagmahaltabatinbi maka kalasahinbi saga pagnakura'an ilu ma sabab hinang sigām ma ka'am. Magsulut isab kam dangan maka dangan.",
        14: "Ya na itu isab pangamu' kami ma ka'am, saga dauranakan, amay-amayinbi saga a'a lisu'an, sō'unbi sigām maghinang. Pahogotunbi atay sasuku al'kkas sinōd tāw. Tabanginbi isab saga a'a aluhay tabowa e' sasat. Imaninbi a'a kamemon.",
        15: "Pajaga kam supaya halam aniya' ma ka'am amalosan la'at bang ganta' aniya' angala'at ka'am. Sagō' ya tuyu'anbi sakahaba' waktu subay maghinang ahāp ma pagkahibi angandol ma si Isa Al-Masi, sampay ma saga a'a kamemon.",
        16: "Subay kam magkakōran sakahaba' llaw.",
        17: "Subay kam angamu'-ngamu' na pa'in ni Tuhan.",
        18: "Ai-ai pat'kka ni ka'am, subay kam magsukul sadja sabab ya na kabaya'an Tuhan subay hinangbi pagka si Isa Al-Masi ya parakayu'anbi.",
        19: "Da'a sagga'unbi ai-ai nihinang e' Rū Sussi ma deyomanbi.",
        20: "Da'a palehomunbi saga bissala ya pinabissala e' Tuhan.",
        21: "Sagō' pariksa'unbi ai-ai takalebi. Bang ahāp, bogboginbi.",
        22: "Halli'inbi la'at indaginis.",
        23: "Mura-murahan, bang pa'in pinasussi kajarihanbi kamemon e' Tuhan, ya amuwan kasannangan atay. Mura-murahan isab, bang pa'in jagahanna nyawabi maka pikilanbi maka baranbi bo' halam aniya' tamakbi ma waktu pagbīng pi'itu Panghū'tam si Isa Al-Masi.",
        24: "Tantu itu nihinang e' Tuhan ya bay amene' ka'am, sabab kapangandolan iya to'ongan.",
        25: "Saga dauranakanku, amu'inbi isab kami tabang ni Tuhan.",
        26: "Siyumunbi saga danakantam mailu kamemon, tanda' pagaddat kami ma sigām.",
        27: "Aniya' kapatutku min Panghū', ya angkan kam soho'ku amassa sulat itu ni pagkahibi kamemon ya angandol ma si Isa.",
        28: "Mura-murahan, bang pa'in kam pinaniya'an tatabangan min Panghū'tam si Isa Al-Masi. Wassalam",
    },
}
